def calculate_aliens(N: int, M: int, H: list) -> int:
    count = 0
    for i in range(N):
        if H[i] > M:
            break
        else:
            M -= H[i]
            count += 1
    return count

# Example usage
N, M = map(int, input().split())
H = list(map(int, input().split()))
print(calculate_aliens(N, M, H))
